import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>PNG 标志很清晰，但也很重，一张 PNG 头图可能有好几 MB。转成 WebP 后透明度和锐利度都在，文件却大幅缩小了。</p>\n<p>每张图片的转换只要几秒钟，整套图标也可以一次转完。全部在浏览器里运行，不用安装任何东西。</p>\n<p>这篇指南一步一步带你走完流程，并给出能保护透明度和文字的设置。</p>\n<h2 id=\"before-you-start\">开始之前：需要准备什么</h2>\n<p>你需要 PNG 文件和一个现代浏览器。Chrome、Edge、Firefox 和 Safari 都行，电脑和手机上都能用。</p>\n<p>先看 PNG 有没有透明部分。标志、图标和抠出来的产品图通常有，截图和照片通常没有。</p>\n<p>还要知道 WebP 文件要用到哪里。网站用 80% 到 85% 画质就行，必须完美的标志则要用 90%。</p>\n<p>单个文件最大支持 25MB，大截图、高清屏截图和高分辨率产品渲染图都不用提前处理，直接就能转。</p>\n<h2 id=\"step-1-open-tool\">第 1 步：打开 PNG 转 WebP 工具</h2>\n<p>在浏览器里打开 <a href=\"/zh/png-zhuan-webp/\">PNG 转 WebP 工具</a>。Windows、Mac、Linux、ChromeOS、安卓和 iOS 都能用。</p>\n<p>页面上有上传区、画质滑块和转换按钮这三个控件，整个操作就是它们了。</p>\n<p>不用注册账号，文件也不会上传。转换就在你的设备上完成，客户的标志和私人截图也不用担心外泄。</p>\n<p>用手机的话，直接在手机浏览器里打开这个页面就行。点一下上传区，就能从相册里选 PNG 文件。</p>\n<h2 id=\"step-2-upload\">第 2 步：上传 PNG 文件</h2>\n<p>把 PNG 文件拖到上传区，或者点一下打开文件选择器。一次选多个文件，就能批量转换。</p>\n<p>每个文件都会显示为一张卡片，带有缩略图、尺寸和文件大小。快速扫一眼，就能确认传对了文件，没有多余的混进来。</p>\n<p>电脑上还能用 Ctrl+V 直接粘贴剪贴板里的图片。PNG 图片在别的软件里复制好之后，这个办法很方便。</p>\n<p>隔行扫描的 PNG 也支持。解码器能正常读取，不用先做别的转换。</p>\n<h2 id=\"step-3-quality\">第 3 步：设置画质滑块</h2>\n<p>透明标志把画质设到 85% 到 90%。边缘保持锐利，文件却比 PNG 小得多。</p>\n<p>带文字的截图用 85%，字保持可读，文件大幅缩小。画质再低，小字会变软。</p>\n<p>存成 PNG 的照片用 80% 到 85% 最合适。照片看起来干净，文件只有 PNG 的零头。</p>\n<p>头图用 80%，大小和画质平衡得很好。图片铺满屏幕，文件又小到能快速加载。</p>\n<h2 id=\"step-4-convert\">第 4 步：转换文件</h2>\n<p>点“转换”按钮。工具会解码每个 PNG，把它画到画布上，再编码成 WebP。</p>\n<p>转换很快，每张通常只要一两秒。文件越大花的时间越长一点，因为要编码的像素更多。</p>\n<p>每张卡片都会更新，显示新的 WebP 大小和原来的 PNG 大小。一次好的转换能省下很多体积，照片和截图尤其明显。</p>\n<p>某个文件失败了就读一下报错信息。损坏的 PNG 或改错名字的文件是最常见的原因，整批里其余的文件会继续转换。</p>\n<h2 id=\"step-5-verify-transparency\">第 5 步：确认透明度还在</h2>\n<p>点标志卡片上的“对比”，就能并排看到 PNG 和 WebP。放大看边缘，确认透明度干净。</p>\n<p>留意标志周围的光晕或毛边。透明处出现白色或彩色边缘，说明画质太低，提高画质就能修好。</p>\n<p>柔和的阴影也要检查。投影应该渐渐淡出，而不是一层一层地断开，分层就说明画质设置太激进了。</p>\n<p>透明度看着不对就把画质提高 5 个点再转一次。原 PNG 还留在队列里，不用重新上传。</p>\n<h2 id=\"step-6-download\">第 6 步：下载 WebP 文件</h2>\n<p>点单张卡片上的“下载”，就能保存这一张 WebP。文件名保持原名，只把后缀换成 .webp。</p>\n<p>批量转换时，点“全部下载”可以拿到一个 ZIP，里面装着所有转好的 WebP。这比一张一张下载快得多。</p>\n<p>用之前先检查一遍下载好的文件。在浏览器里打开一张 WebP，确认显示正常，透明度完好。</p>\n<p>原 PNG 文件也留着。WebP 永远变不回完美的 PNG，原件就是你的保险。</p>\n<ol>\n<li>打开 PNG 转 WebP 工具，上传 PNG 文件。</li>\n<li>标志的画质滑块设到 85%。</li>\n<li>转换后用对比功能确认透明度。</li>\n<li>单张下载 WebP 文件，或整批打包成 ZIP 下载。</li>\n</ol>\n<h2 id=\"converting-an-icon-set\">整套图标一起转换</h2>\n<p>在文件选择器里一次选中所有 PNG 图标。它们会全部进入队列，点一下就能全部转成 WebP。</p>\n<p>整套用同一个画质设置。图标常常一起出现，画质不一致看起来会参差不齐。</p>\n<p>转换后抽查两三张图标就行，不用五十张全看。设置相同，抽查的几张没问题，其余的也不会有问题。</p>\n<p>把 WebP 图标上传到网站，替换掉原来的 PNG。再更新引用，测试一下页面，确认所有图标都正常显示。</p>\n<h2 id=\"changing-quality-after\">转换后还能改画质</h2>\n<p>转换后不用重新上传就能改画质滑块。原 PNG 还留在队列里，换个设置点一下就行。</p>\n<p>先试 85%，再试 80%，把两个结果对比一下。差别常常肉眼看不出来，那就选更小的那个文件。</p>\n<p>特别重要的单个标志，也可以试试 90%。最好的设置就是看不出差别的最低画质。</p>\n<p>换设置之前先把当前版本下载下来。下载按钮保存的是当前这次转换，改了设置就得重新下载。</p>\n<h2 id=\"fixing-problems\">常见问题怎么修</h2>\n<p>WebP 比 PNG 还大，说明这张图可能特别简单。留着这张 PNG 就行，继续处理其他的。</p>\n<p>标志边缘看着有毛边，是画质太低了。把滑块拉到 90%，用原 PNG 再转一次。</p>\n<p>颜色看着偏移了，可能是 PNG 的色彩配置没能保留下来。把 WebP 和 PNG 仔细对比一下，偏移很要紧就留着 PNG。</p>\n<p>某个文件转失败了，先确认它是不是真正的 PNG。一个实际是 JPG 或 WebP、名字却叫 .png 的文件会让解码器糊涂。</p>\n<h2 id=\"uploading-to-your-site\">把 WebP 上传到网站</h2>\n<p>把转好的 WebP 文件像其他图片一样上传到媒体库。WordPress、Shopify 和 Wix 现在都接受 WebP 上传了。</p>\n<p>先测试一张图片。上传它，打开页面，确认显示正常，透明度完好。</p>\n<p>老浏览器用 PNG 备用版。大多数平台会自动处理，也可以自己在 HTML 里用 picture 元素实现。</p>\n<p>切换后测一下页面速度。用了 WebP 图片的页面应该明显变快，转换的意义就在这里。</p>\n<h2 id=\"converting-logo-website\">为网站转换标志</h2>\n<p>网站标志既要加载快，又要在每块屏幕上都锐利。PNG 转 WebP 用 90% 画质，两点都能做到，透明度也还在。</p>\n<p>转换后在网站实际背景上检查标志。在白色上看着完美的标志，画质太低时在彩色页眉上可能出现淡淡的毛边。</p>\n<p>发布前在电脑和手机上都测试一下标志。大屏幕上锐利的标志，在小屏幕上可能变软，快速测试就能发现问题。</p>\n<p>留着 PNG 原件给老浏览器做备用。picture 元素给现代浏览器提供 WebP，给其他浏览器提供 PNG，每个访客都能看到标志。</p>\n<p>每页都出现的标志，速度上的节省最重要。页眉标志每次页面浏览都要加载，文件小一点，每次访问都快一点。</p>\n<h2 id=\"converting-icons-app\">为应用转换图标</h2>\n<p>应用图标出现在很多尺寸下，从小小的网站图标到大大的商店列表图都有。用 90% 画质转成 WebP，图标保持锐利，占用存储还比 PNG 少。</p>\n<p>整套图标用同一个画质设置。图标常常一起出现，画质不一致看起来会参差不齐。</p>\n<p>发布前在浅色和深色背景上都测试一下图标。依赖白色背景的图标在深色主题下会直接消失，解决办法是用透明版本。</p>\n<p>上架应用商店前，先查平台的格式规则。有的商店接受 WebP，有的只认 PNG，格式必须符合商店的要求。</p>\n<p>转换后把 PNG 母版留在项目文件夹里。万一哪个商店或平台拒绝 WebP，PNG 马上就能用，不用重新转换。</p>\n<h2 id=\"converting-screenshots-blog\">为博客转换截图</h2>\n<p>博客截图需要文字清晰可读，WebP 用 85% 画质就能让字保持锐利。同样大小下文字比 JPG 更干净，教程图片尤其需要这一点。</p>\n<p>截图一次批量转换，全部用同一个画质。同一篇文章里的图片画质不一致，看起来会参差不齐。</p>\n<p>转换后用对比查看器检查最小的文字。放大看菜单和正文，发布前确认读起来干净清晰。</p>\n<p>转换后更新博客文章里的图片引用。引用坏了比加载慢更糟，所以页面上的每张图片都要检查。</p>\n<p>把 PNG 原件留在媒体库里做备用。读者的浏览器显示不了 WebP 时，会加载 PNG 版本，谁都不会看到破损图片。</p>\n<h2 id=\"converting-product-images\">转换产品图片</h2>\n<p>产品图片要格外小心，因为顾客会放大看。用 80% 到 85% 画质转成 WebP，面料质感和小细节才能保留下来。</p>\n<p>转换前按分类整理产品。鞋子、衬衫和配饰可能需要不同的设置，先分好类，每组就能一次干净地批量转换。</p>\n<p>转换后抽查三四件产品就行，不用五百件全看。同一批设置相同，抽查的几件没问题，其余的也不会有问题。</p>\n<p>上传 WebP 文件，更新产品列表。再在电脑和手机上测试几个产品页，确认图片显示正常。</p>\n<p>原 JPG 或 PNG 也留着，因为有些平台只认它们。同一件产品既上亚马逊又上自家店铺，两种格式都要备好。</p>\n<h2 id=\"converting-presentation-images\">为演示文稿转换图片</h2>\n<p>演示文稿里的图片既要清晰，体积又要合理。幻灯片里的 PNG 截图看着锐利，WebP 版却小得多，加载也更快。</p>\n<p>幻灯片里的截图用 90% 画质转成 WebP。文字在投影上保持可读，文件也小到能让整份文稿保持可控。</p>\n<p>整页铺满的照片用 85% 画质 WebP 就行。照片看着干净，幻灯片加载快，观众看到的是图片本身，而不是像素点。</p>\n<p>转换后看一下整份文稿的大小。超过 50MB 的文稿发邮件或上传都费劲，转换图片往往就是解决办法。</p>\n<p>演讲前先在投影仪上测试一下文稿。笔记本上锐利的幻灯片，投影出来可能变软，提前测试就能早点发现问题。</p>\n<h2 id=\"converting-client-brand-assets\">转换客户的品牌素材</h2>\n<p>客户的品牌素材常常以 PNG 形式发来，网站却需要 WebP。整套素材一次转换，用同一个画质设置，品牌才能保持一致。</p>\n<p>转换前先和客户商量好画质设置。标志要 90%，照片要 80%，得分开批量转，所以素材要先分好类。</p>\n<p>转换后检查品牌颜色，因为饱和色可能轻微偏移。快速和 PNG 原件对比一下，就能确认颜色是否一致。</p>\n<p>两种格式都交给客户。WebP 文件放到网站上，PNG 原件留在品牌文件夹里，供编辑和打印使用。</p>\n<p>在项目笔记里记下转换设置。简单一句话，就能让下一个接手的人不用猜素材到底是 80% 还是 90% 的 WebP。</p>\n<h2 id=\"webp-for-online-courses\">在线课程用 WebP</h2>\n<p>在线课程里全是截图和图表，WebP 能在 PNG 体积的零头里保持可读。几百张图的课程转成 WebP 后，加载快得多。</p>\n<p>课程截图用 85% 画质转成 WebP。文字保持可读，文件大幅缩小，课程用起来明显更快。</p>\n<p>每个标注都必须完美的图表，那就考虑无损 WebP 或 PNG。有损 WebP 很好，但对精细文字来说还不够完美。</p>\n<p>转换后更新图片引用，再测试一下课程。引用坏了比加载慢更糟，更新后每节课都要检查。</p>\n<p>把 PNG 原件留在课程仓库里做备用。学生的浏览器显示不了 WebP 时，会加载 PNG 版本，谁都不会看到破损图片。</p>\n<p>整个流程就是：上传、设置画质、确认透明度、下载。想了解背后的原理，可以看<a href=\"/zh/blog/png-zhuan-webp-wanquan-zhinan/\">PNG 转 WebP 完全指南</a>；正面对照可以看<a href=\"/zh/blog/png-vs-webp-duibi/\">PNG vs WebP：透明度与文件大小对比</a>。如果目的地要求 JPG，<a href=\"/zh/png-zhuan-jpg/\">PNG 转 JPG 工具</a>就是对应的工具。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"转换后怎么确认透明度保留下来了？","answer":"点标志卡片上的“对比”，就能并排看到 PNG 和 WebP。放大看边缘，找找有没有光晕或毛边，出现就说明画质太低。柔和的阴影也要检查，应该渐渐淡出而不是一层层断开。哪里不对就提高画质再转一次。"},{"question":"PNG 截图转 WebP，文字会变模糊吗？","answer":"画质保持在 85% 就不会。同样文件大小下，WebP 保留文字的效果比 JPG 好，截图保持可读。下载前用对比查看器放大看最小的文字，字看着发软就提高画质。"},{"question":"转换接受的 PNG 最大是多大？","answer":"每个 PNG 文件最大 25MB，大截图、高清屏截图和高分辨率产品渲染图都能覆盖。转换在你的设备上运行，大文件按本地速度处理，不用等上传。"},{"question":"转换后不重新上传，能改画质吗？","answer":"可以。第一次转换后原 PNG 还留在队列里，移动画质滑块就能再转一次。换设置之前先把当前版本下载下来，因为下载按钮保存的是当前这次转换。"},{"question":"PNG 转 WebP 在手机浏览器上能用吗？","answer":"可以。在手机浏览器里打开工具，从相册里选 PNG，再下载转好的 WebP。转换就在手机上完成，文件会下载到你的设备里。手机上批量别贪多，大 PNG 在手机上编码比较慢。"},{"question":"什么时候选 PNG 转 WebP，而不是 PNG 转 JPG？","answer":"图片带透明度，或者要放到网站上时选 WebP，因为 WebP 保留透明通道，文件还更小。目的地有明确要求时选 JPG，比如表单、打印机或邮件，那里兼容性比体积更重要。"}];
